SELECT 
FROM evw_LdxRegLeave_all
WHERE evw_LdxRegLeave_all.BADGE = #{badge, jdbcType = VARCHAR}

	AND CONVERT(VarChar(7), evw_LdxRegLeave_all.BEGINTIME, 120) = #{ queryMonth, jdbcType = VARCHAR }

ORDER BY evw_LdxRegLeave_all.BEGINTIME

SELECT 
FROM evw_LdxRegLeave_all
WHERE evw_LdxRegLeave_all.BADGE = #{badge, jdbcType = VARCHAR}

	AND CONVERT(VarChar(10), evw_LdxRegLeave_all.BEGINTIME, 120) >= #{ queryDay, jdbcType = VARCHAR }

ORDER BY evw_LdxRegLeave_all.BEGINTIME
